/// 分野（Domain）> 大項目（Major）> 中項目（Mid）> トピック（Topic）
/// のツリー構造を型で表現するためのモデル。

class Topic {
  final String id;     // 内部ID（=既存のラベルでもOK）
  final String label;  // 表示名
  const Topic({required this.id, required this.label});
}

class MidCategory {
  final String id;
  final String label;
  final List<Topic> topics;
  const MidCategory({
    required this.id,
    required this.label,
    required this.topics,
  });
}

class MajorCategory {
  final String id;
  final String label;
  final List<MidCategory> mids;
  const MajorCategory({
    required this.id,
    required this.label,
