/// 分野〜トピックを指すパス（履歴保存・選定結果の受け渡しに便利）
class CategoryPath {
  final String domainId;
  final String majorId;
  final String? midId;
  final String? topicId;
  const CategoryPath({
    required this.domainId,
    required this.majorId,
    this.midId,
    this.topicId,
  });

  CategoryPath copyWith({
    String? domainId,
    String? majorId,
    String? midId,
    String? topicId,
  }) {
    return CategoryPath(
      domainId: domainId ?? this.domainId,
      majorId: majorId ?? this.majorId,
      midId: midId ?? this.midId,
      topicId: topicId ?? this.topicId,
    );
  }
}

/// （任意）状況設定の観点コードを型で扱うためのenum
enum ScenarioAspect { A, B, C, D, E }

extension ScenarioAspectX on ScenarioAspect {
  String get code => toString().split('.').last; // 'A'..'E'
  static ScenarioAspect? fromCode(String? c) {
    if (c == null) return null;
    switch (c) {
      case 'A': return ScenarioAspect.A;
      case 'B': return ScenarioAspect.B;
      case 'C': return ScenarioAspect.C;
      case 'D': return ScenarioAspect.D;
      case 'E': return ScenarioAspect.E;
    }
    return null;
  }
}

// lib/models/history_models.dart

/// 1問ぶんの履歴を表すモデル。
/// 既存の保存形式に合わせて Map との相互変換も用意しています。
class HistoryRecord {
  final DateTime timestamp;   // 解答時刻
  final String difficulty;    // '必修問題' / '一般問題' / '状況設定問題'
  final String domain;        // 分野
  final String major;         // 大項目
  final String? mid;          // 中項目（任意）
  final String? topic;        // トピック（任意）
  final bool correct;         // 正解なら true
  final int? elapsedMs;       // 解答に要した時間（ミリ秒／任意）

  const HistoryRecord({
    required this.timestamp,
    required this.difficulty,
    required this.domain,
    required this.major,
    this.mid,
    this.topic,
    required this.correct,
    this.elapsedMs,
  });

  /// Map -> HistoryRecord（ストレージや既存JSONからの復元用）
  factory HistoryRecord.fromMap(Map<String, dynamic> map) {
    final ts = map['timestamp'];
    // ISO8601文字列またはミリ秒UNIXの両対応
    final DateTime t = ts is int
        ? DateTime.fromMillisecondsSinceEpoch(ts)
        : DateTime.tryParse(ts?.toString() ?? '') ?? DateTime.now();

    return HistoryRecord(
      timestamp: t,
      difficulty: (map['difficulty'] ?? '').toString(),
      domain: (map['domain'] ?? '').toString(),
      major: (map['major'] ?? '').toString(),
      mid: map['mid']?.toString(),
      topic: map['topic']?.toString(),
      correct: (map['correct'] == true) || (map['isCorrect'] == true),
      elapsedMs: map['elapsedMs'] is int ? map['elapsedMs'] as int : null,
    );
  }

  /// HistoryRecord -> Map（保存・共有用）
  Map<String, dynamic> toMap() {
    return {
      'timestamp': timestamp.toIso8601String(),
      'difficulty': difficulty,
      'domain': domain,
      'major': major,
      if (mid != null) 'mid': mid,
      if (topic != null) 'topic': topic,
      'correct': correct,
      if (elapsedMs != null) 'elapsedMs': elapsedMs,
    };
  }
}

/// 日別要約（チャートに載せやすい形）
class DailySummary {
  final DateTime date; // 時刻は 00:00 固定
  final int total;
  final int correct;
  double get accuracy => total == 0 ? 0 : correct / total;

  const DailySummary({
    required this.date,
    required this.total,
    required this.correct,
  });
}

/// ドメイン別要約
class DomainSummary {
  final String domain;
  final int total;
  final int correct;
  double get accuracy => total == 0 ? 0 : correct / total;

  const DomainSummary({
    required this.domain,
    required this.total,
    required this.correct,
  });
}

/// ローリング（移動平均）精度の一点
class RollingPoint {
  final DateTime date;
  final double accuracy; // 0..1
  const RollingPoint({required this.date, required this.accuracy});
}

/// 連続正解/不正解の情報
class Streaks {
  final int currentCorrect; // 直近の連続正解数
  final int bestCorrect;    // 過去最大の連続正解数
  final int currentWrong;   // 直近の連続不正解数
  final int bestWrong;      // 過去最大の連続不正解数

  const Streaks({
    required this.currentCorrect,
    required this.bestCorrect,
    required this.currentWrong,
    required this.bestWrong,
  });
}

// lib/models/notice.dart
import 'package:flutter/foundation.dart';

/// アプリ内のお知らせ情報
class Notice {
  final String id;
  final String title;
  final String body;
  final DateTime publishedAt;
  final bool pinned; // 重要なお知らせかどうか

  const Notice({
    required this.id,
    required this.title,
    required this.body,
    required this.publishedAt,
    this.pinned = false,
  });

  /// JSON から Notice を生成
  factory Notice.fromJson(Map<String, dynamic> json) {
    return Notice(
      id: json['id'] as String,
      title: json['title'] as String,
      body: json['body'] as String,
      publishedAt: DateTime.parse(json['publishedAt'] as String),
      pinned: json['pinned'] as bool? ?? false,
    );
  }

  Map<String, dynamic> toJson() {
    return {
      'id': id,
      'title': title,
      'body': body,
      'publishedAt': publishedAt.toIso8601String(),
      'pinned': pinned,
    };
  }

  /// 日付表示用（例: 2025/11/19）
  String get dateLabel {
    final y = publishedAt.year.toString().padLeft(4, '0');
    final m = publishedAt.month.toString().padLeft(2, '0');
    final d = publishedAt.day.toString().padLeft(2, '0');
    return '$y/$m/$d';
  }
}

// lib/models/nurai_question.dart
class NuraiQuestion {
  final String questionText;
  final Map<String, String> choices;

  /// 正解ラベル（例: ["3"] / ["2","4"] / 入力式なら ["3.8"] など）
  final List<String> correctLabels;

  /// 各選択肢の根拠（任意）
  final Map<String, String>? rationales;

  /// 解説（任意）
  final String? explanation;

  /// single / multiple / select_incorrect / input（必要なら）
  final String questionKind;

  /// 複数選択の必要正解数
  final int requiredCorrectCount;

  /// 難易度など（任意）
  final String difficulty;
  final String domain;
  final String major;
  final String? mid;
  final String? topic;

  /// 過去問
  final String sourceType;
  final String? sourceTag;

  /// ★ 画像パス（assets のパス）
  /// 例: assets/fig/111/am_q11_femur.png
  final String? imagePath;

  /// ★ 画像が必要か（任意）
  final bool imageRequired;

  const NuraiQuestion({
    required this.questionText,
    required this.choices,
    required this.correctLabels,
    this.rationales,
    this.explanation,
    this.questionKind = 'single',
    required this.requiredCorrectCount,
    this.difficulty = '',
    this.domain = '',
    this.major = '',
    this.mid,
    this.topic,
    this.sourceType = 'past_exam',
    this.sourceTag,
    this.imagePath,
    this.imageRequired = false,
  });

  /// 複数選択（誤答選択も複数になり得る）
  bool get isMultiple => questionKind == 'multiple' || questionKind == 'select_incorrect';

  /// 入力式（計算問題など）：choices が空でも input とみなす
  bool get isInput => questionKind == 'input' || choices.isEmpty;

  bool get hasImage => (imagePath ?? '').trim().isNotEmpty;
}

// lib/models/past_exam_history.dart
import 'dart:convert';

import 'package:flutter/foundation.dart';
import 'package:shared_preferences/shared_preferences.dart';

/// 過去問の解答1件（スナップショット込み）
///
/// 画面側が参照する可能性があるフィールド/Getterは「ここに集約」して固定する。
class PastExamAnswerRecord {
  // 識別
  final String examId; // '111' など
  final String questionKey; // ユニーク（例: '第111回 一般問題 午前 1問'）
  final bool isCorrect;

  // 表示用メタ
  final String? examTitle; // '第111回（2022年）'
  final String? partLabel; // '一般問題 午前'
  final String? partKind; // '必修' / '一般' / '状況設定'
  final int? questionNo; // 1,2,3...

  // スナップショット
  final String? questionText;
  final Map<String, String>? choices;
  final List<String>? correctLabels;
  final List<String>? selectedLabels;
  final String? explanation;
  final Map<String, String>? rationales;

  // 画像
  final String? imagePath;

  // 回答日時（ms）
  final int answeredAtMs;

  const PastExamAnswerRecord({
    required this.examId,
    required this.questionKey,
    required this.isCorrect,
    required this.answeredAtMs,
    this.examTitle,
    this.partLabel,
    this.partKind,
    this.questionNo,
    this.questionText,
    this.choices,
    this.correctLabels,
    this.selectedLabels,
    this.explanation,
    this.rationales,
    this.imagePath,
  });

  /// 互換：画面が昔 `ts` を参照していた
  DateTime get ts => DateTime.fromMillisecondsSinceEpoch(answeredAtMs);

  /// 互換：画面が `hasSnapshot` を参照していた
  bool get hasSnapshot => (questionText ?? '').trim().isNotEmpty;

  /// 互換：画面が `hasImage` を参照していた
  bool get hasImage => (imagePath ?? '').trim().isNotEmpty;

  /// ✅ 互換：古い画面コードが `choiceLabel` を参照していた場合の救済
  /// 選択ラベルがあれば "A" / "2" などを結合して返す（無ければ null）
  String? get choiceLabel {
    final list = (selectedLabels ?? const <String>[])
        .map((e) => e.trim())
        .where((e) => e.isNotEmpty)
        .toList();
    if (list.isEmpty) return null;
    return list.join(',');
  }

  /// ✅ 午前/午後判定（partLabel/partKindが空でも推測）
  bool get isAM {
    final t = '${partLabel ?? ''} ${partKind ?? ''}'.trim();
    return t.contains('午前') || t.toLowerCase().contains('_am');
  }

  bool get isPM {
    final t = '${partLabel ?? ''} ${partKind ?? ''}'.trim();
    return t.contains('午後') || t.toLowerCase().contains('_pm');
  }

  Map<String, dynamic> toJson() {
    return {
      'examId': examId,
      'questionKey': questionKey,
      'isCorrect': isCorrect,
      'answeredAtMs': answeredAtMs,
      'examTitle': examTitle,
      'partLabel': partLabel,
      'partKind': partKind,
      'questionNo': questionNo,
      'questionText': questionText,
      'choices': choices,
      'correctLabels': correctLabels,
      'selectedLabels': selectedLabels,
      'explanation': explanation,
      'rationales': rationales,
      'imagePath': imagePath,
    };
  }

  static PastExamAnswerRecord fromJson(Map<String, dynamic> j) {
    Map<String, String>? mapSS(dynamic v) {
      if (v == null) return null;
      final m = Map<String, dynamic>.from(v as Map);
      return m.map((k, vv) => MapEntry(k.toString(), (vv ?? '').toString()));
    }

    List<String>? listS(dynamic v) {
      if (v == null) return null;
      return (v as List).map((e) => (e ?? '').toString()).toList();
    }

    int? parseInt(dynamic v) {
      if (v == null) return null;
      if (v is int) return v;
      return int.tryParse(v.toString());
    }

    return PastExamAnswerRecord(
      examId: (j['examId'] ?? '').toString(),
      questionKey: (j['questionKey'] ?? '').toString(),
      isCorrect: (j['isCorrect'] ?? false) as bool,
      answeredAtMs: (j['answeredAtMs'] ?? 0) as int,
      examTitle: j['examTitle']?.toString(),
      partLabel: j['partLabel']?.toString(),
      partKind: j['partKind']?.toString(),
      questionNo: parseInt(j['questionNo']),
      questionText: j['questionText']?.toString(),
      choices: mapSS(j['choices']),
      correctLabels: listS(j['correctLabels']),
      selectedLabels: listS(j['selectedLabels']),
      explanation: j['explanation']?.toString(),
      rationales: mapSS(j['rationales']),
      imagePath: j['imagePath']?.toString(),
    );
  }
}

/// 年度集計（ solved / correct だけを安定提供）
class PastExamYearSummary {
  final int solved;
  final int correct;

  const PastExamYearSummary({required this.solved, required this.correct});

  double get accuracy => solved == 0 ? 0.0 : correct / solved;
}

/// 過去問解答履歴ストア（SharedPreferences）
///
/// ✅ 画面が壊れないように「APIを固定」
/// - versionListenable
/// - all()
/// - recordsForExam(examId)
/// - solvedCountMap(examIds)
/// - summaryMap(examIds)
/// - resetExam(examId)
/// - clearAll()
/// - upsertAnswerWithSnapshot(...)
class PastExamHistory {
  PastExamHistory._();
  static final PastExamHistory instance = PastExamHistory._();

  static const _prefsKey = 'past_exam_history_v4';

  final ValueNotifier<int> _version = ValueNotifier<int>(0);
  ValueListenable<int> get versionListenable => _version;

  bool _loaded = false;

  /// 内部は「ユニークキー -> Record」
  /// ユニークキーは `examId::questionKey`
  final Map<String, PastExamAnswerRecord> _map = {};

  String _k(String examId, String questionKey) => '$examId::$questionKey';

  void _bump() => _version.value = _version.value + 1;

  Future<void> _ensureLoaded() async {
    if (_loaded) return;
    _loaded = true;

    final prefs = await SharedPreferences.getInstance();
    final raw = prefs.getString(_prefsKey);
    if (raw == null || raw.trim().isEmpty) return;

    try {
      final decoded = jsonDecode(raw);

      // v4: Map<String, dynamic>（key -> recordJson）
      if (decoded is Map) {
        final m = Map<String, dynamic>.from(decoded);
        for (final e in m.entries) {
          final v = e.value;
          if (v is Map) {
            final rec = PastExamAnswerRecord.fromJson(
              Map<String, dynamic>.from(v),
            );
            _map[_k(rec.examId, rec.questionKey)] = rec;
          }
        }
        return;
      }

      // 旧: List（recordJson の配列）
      if (decoded is List) {
        for (final item in decoded) {
          if (item is Map) {
            final rec = PastExamAnswerRecord.fromJson(
              Map<String, dynamic>.from(item),
            );
            _map[_k(rec.examId, rec.questionKey)] = rec;
          }
        }
      }
    } catch (_) {
      // 壊れたJSONは無視（クラッシュ回避）
    }
  }

  Future<void> _save() async {
    final prefs = await SharedPreferences.getInstance();
    final data = <String, dynamic>{};
    for (final e in _map.entries) {
      data[e.key] = e.value.toJson();
    }
    await prefs.setString(_prefsKey, jsonEncode(data));
  }

  /// 全件（新しい順）
  Future<List<PastExamAnswerRecord>> all() async {
    await _ensureLoaded();
    final list = _map.values.toList()
      ..sort((a, b) => b.answeredAtMs.compareTo(a.answeredAtMs));
    return list;
  }

  /// 年度（examId）だけ（新しい順）
  Future<List<PastExamAnswerRecord>> recordsForExam(String examId) async {
    await _ensureLoaded();
    final list = _map.values.where((r) => r.examId == examId).toList()
      ..sort((a, b) => b.answeredAtMs.compareTo(a.answeredAtMs));
    return list;
  }

  /// 年度ごとの「解答済み数」
  Future<Map<String, int>> solvedCountMap(List<String> examIds) async {
    await _ensureLoaded();
    final out = <String, int>{for (final id in examIds) id: 0};

    for (final r in _map.values) {
      if (out.containsKey(r.examId)) {
        out[r.examId] = (out[r.examId] ?? 0) + 1;
      }
    }
    return out;
  }

  /// 年度ごとの solved/correct 集計
  Future<Map<String, PastExamYearSummary>> summaryMap(List<String> examIds) async {
    await _ensureLoaded();
    final solved = <String, int>{for (final id in examIds) id: 0};
    final correct = <String, int>{for (final id in examIds) id: 0};

    for (final r in _map.values) {
      if (!solved.containsKey(r.examId)) continue;
      solved[r.examId] = (solved[r.examId] ?? 0) + 1;
      if (r.isCorrect) {
        correct[r.examId] = (correct[r.examId] ?? 0) + 1;
      }
    }

    final out = <String, PastExamYearSummary>{};
    for (final id in examIds) {
      out[id] = PastExamYearSummary(
        solved: solved[id] ?? 0,
        correct: correct[id] ?? 0,
      );
    }
    return out;
  }

  /// 1問ぶんを保存（既存があれば上書き）
  ///
  /// ★ 画面側の変更で壊れないよう、ここは引数を安定させる
  Future<void> upsertAnswerWithSnapshot({
    required String examId,
    required String questionKey,
    required bool isCorrect,

    /// 互換：古い実装が answeredAt を必須にしていたケースがあるので optional
    DateTime? answeredAt,

    // 表示用
    String? examTitle,
    String? partLabel,
    String? partKind,
    int? questionNo,

    // snapshot
    String? questionText,
    Map<String, String>? choices,
    List<String>? correctLabels,
    List<String>? selectedLabels,
    String? explanation,
    Map<String, String>? rationales,

    // image
    String? imagePath,
  }) async {
    await _ensureLoaded();

    final now = answeredAt ?? DateTime.now();
    final rec = PastExamAnswerRecord(
      examId: examId,
      questionKey: questionKey,
      isCorrect: isCorrect,
      answeredAtMs: now.millisecondsSinceEpoch,
      examTitle: examTitle,
      partLabel: partLabel,
      partKind: partKind,
      questionNo: questionNo,
      questionText: questionText,
      choices: choices,
      correctLabels: correctLabels,
      selectedLabels: selectedLabels,
      explanation: explanation,
      rationales: rationales,
      imagePath: imagePath,
    );

    _map[_k(examId, questionKey)] = rec;
    await _save();
    _bump();
  }

  /// 年度ごとにリセット（examId）
  Future<void> resetExam(String examId) async {
    await _ensureLoaded();
    final keys = _map.keys.where((k) => k.startsWith('$examId::')).toList();
    for (final k in keys) {
      _map.remove(k);
    }
    await _save();
    _bump();
  }

  /// 全消し
  Future<void> clearAll() async {
    await _ensureLoaded();
    _map.clear();
    final prefs = await SharedPreferences.getInstance();
    await prefs.remove(_prefsKey);
    _bump();
  }
}
